param([string]$Root = $PSScriptRoot)
$ErrorActionPreference = 'Stop'
$Root = [IO.Path]::GetFullPath($Root)
$inputDir = Join-Path $Root 'inputs'
$out = Join-Path $Root 'notes'
$archive = Join-Path $out 'archive'
[IO.Directory]::CreateDirectory($archive) | Out-Null
$lock = $null
try { $lock = [IO.File]::Open((Join-Path $out '.run.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None) }
catch { throw 'Another run is active. Wait for it to finish and try again.' }
try {
$utf8 = New-Object Text.UTF8Encoding($false, $true)
function Hash([byte[]]$bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
}
function WriteAtomic($path, $text) {
    $temp = "$path.tmp"
    [IO.File]::WriteAllText($temp, $text, (New-Object Text.UTF8Encoding($true)))
    if ([IO.File]::Exists($path)) { [IO.File]::Replace($temp, $path, "$path.previous") } else { [IO.File]::Move($temp, $path) }
}
function Esc($s) { return [Net.WebUtility]::HtmlEncode([string]$s) }
$recordVersion = 4
function Classify($line) {
    $unknown = '需确认（保留原文，未视为决定）'
    # Labels carry no approval evidence. Quoted objects may remain objects, but
    # vocabulary inside a quote cannot establish the surrounding assertion.
    $body = ($line -replace '^(决定|决议|待办)\s*[:：]\s*', '').Trim()
    $evidence = $body -replace '\u201c[^\u201d]*\u201d|「[^」]*」|『[^』]*』|"[^"]*"|\u2018[^\u2019]*\u2019', '〈引文〉'
    # Separate modality / lack of resolution from a settled negative action.
    $pending = '(未定|未确定|未确认|未批准|未决定|尚未|还没|还未|尚待|仍待|待[^。；;]*(确认|批准|审批|决定|评估)|没有[^。；;]*(定下|确认|批准|决定|形成|达成|结论|共识)|未能|未达成|无定论|无结论|未形成|有待|暂定|拟议|拟[^。；;]*(实施|采用|上线)|希望|考虑|可能|也许|是否|能否|要不要|如果|若|假如|除非|取决于|以[^。；;]*为准|[？?])'
    $discussion = '((仅|只|暂)[^。；;]{0,6}(讨论|参考|交流|研究)|供[^。；;]{0,6}(讨论|参考)|讨论稿|草案|征求意见|不代表[^。；;]*(批准|通过|决定)|不构成[^。；;]*(批准|通过|决定)|没有[^。；;]*统一|尚无|未获|未经|不确定|不明确)'
    if ($evidence -match $pending -or $evidence -match $discussion) { return $unknown }
    if ($line -match '^待办\s*[:：]') { return '待办（按原文保留）' }
    # Each independent clause needs affirmative evidence. Mixed/complex clauses
    # abstain rather than inheriting certainty from the first matched verb.
    $clauses = @($evidence -split '[。；;！!]|但(?:是)?|不过|然而' | Where-Object { $_.Trim() })
    if (!$clauses.Count) { return $unknown }
    foreach ($clause in $clauses) {
        $c = $clause.Trim()
        $resolved = '^(?:(?:会议|会上|委员会|团队|全体|负责人|大家)\s*)?(?:(?:已|已经|正式|最终|明确|一致)\s*)?(?:决定|决议|确定|确认|批准|同意|通过|否决|驳回|拒绝|不批准|不通过|不同意|禁止|严禁|不得|不允许)\s*[^，,。；;]+$'
        $prohibition = '^不(?:向|对|再|得|允许)[^，,。；;]*(?:公开|披露|提供|发布|发送|使用|执行|实施|上线|开放|销售|收集|保留)[^，,。；;]*$'
        $arrangement = '^(?:首版|本版|本期|本次|新版|第一版|一期|二期)[^，,。；;]{0,12}(?:只|仅)(?:提供|支持|包含|开放|保留)[^，,。；;]+$'
        if ($c -notmatch $resolved -and $c -notmatch $prohibition -and $c -notmatch $arrangement) { return $unknown }
        # A decision about whether to approve is not an approval; nor is a
        # report of the absence of agreement a rejection of the proposal.
        if ($c -match '(不|没有|未)(决定|确认|确定)|(?:决定|确认|确定)\s*(讨论|研究|评估|建议|提议)|(?:批准|通过|同意|决定|确认|确定)\s*(情况|状态|结果|与否)|(?:禁止|严禁|不得|不允许)\s*$') { return $unknown }
    }
    return '决定（原文明确）'
}
$results = @()
$created = 0; $skipped = 0; $failed = 0
if (!(Test-Path -LiteralPath $inputDir)) { throw 'inputs folder does not exist.' }
foreach ($file in @(Get-ChildItem -LiteralPath $inputDir -File -Recurse | Sort-Object FullName)) {
    $relative = $file.FullName.Substring($inputDir.Length + 1)
    try {
        if ($file.Extension.ToLowerInvariant() -notin @('.txt','.md')) { throw 'Only .txt and .md text files are supported.' }
        $bytes = [IO.File]::ReadAllBytes($file.FullName)
        $hash = Hash $bytes
        $pathHash = Hash ($utf8.GetBytes($relative))
        $id = "$pathHash-$hash"
        $recordPath = Join-Path $archive "$id.json"
        $reuse = $false
        if (Test-Path -LiteralPath $recordPath) {
            # Derived cache damage is recoverable from the current input.
            try {
                $record = Get-Content -LiteralPath $recordPath -Raw -Encoding UTF8 | ConvertFrom-Json
                $sourcePath = Join-Path $archive "$id.txt"
                $reuse = $record.version -eq $recordVersion -and $record.id -eq $id -and $record.path -eq $relative -and $record.sha256 -eq $hash -and $null -ne $record.lines -and $null -ne $record.items
                $reuse = $reuse -and (Test-Path -LiteralPath $sourcePath)
                if ($reuse) { $reuse = (Hash ([IO.File]::ReadAllBytes($sourcePath))) -eq $hash }
            } catch { $reuse = $false }
        }
        if ($reuse) {
            $skipped++
        } else {
            $offset = 0
            if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) { $offset = 3 }
            if ($bytes.Length -ge 2 -and $bytes[0] -eq 255 -and $bytes[1] -eq 254) {
                $decoder = New-Object Text.UnicodeEncoding($false,$true,$true); $offset = 2
            } elseif ($bytes.Length -ge 2 -and $bytes[0] -eq 254 -and $bytes[1] -eq 255) {
                $decoder = New-Object Text.UnicodeEncoding($true,$true,$true); $offset = 2
            } else { $decoder = $utf8 }
            $source = $decoder.GetString($bytes,$offset,$bytes.Length-$offset)
            if ([string]::IsNullOrWhiteSpace($source)) { throw 'Empty text file.' }
            if ($source -match '[\x00-\x08\x0B\x0C\x0E-\x1F]') { throw 'Binary/control characters found in text.' }
            $lines = @($source -split '\r\n|\n|\r')
            $items = @()
            for ($i=0; $i -lt $lines.Count; $i++) {
                $line = $lines[$i].Trim()
                if (!$line -or $line -match '^(会议|日期)[:：]') { continue }
                $category = Classify $line
                $items += [pscustomobject]@{line=$i+1; category=$category; text=$line}
            }
            $record = [pscustomobject]@{version=$recordVersion; id=$id; path=$relative; sha256=$hash; processed=(Get-Date).ToString('o'); lines=$lines; items=$items}
            # Commit the preserved source before the record. A retry reuses the same identifiers.
            $sourcePath = Join-Path $archive "$id.txt"
            if (Test-Path -LiteralPath $sourcePath) {
                if ((Hash ([IO.File]::ReadAllBytes($sourcePath))) -ne $hash) {
                    [IO.File]::WriteAllBytes("$sourcePath.tmp",$bytes)
                    [IO.File]::Replace("$sourcePath.tmp",$sourcePath,"$sourcePath.previous")
                }
            } else { [IO.File]::WriteAllBytes($sourcePath,$bytes) }
            WriteAtomic $recordPath ($record | ConvertTo-Json -Depth 8)
            $created++
        }
        $results += [pscustomobject]@{path=$relative; ok=$true; record=$record; error=''}
    } catch {
        $failed++
        $results += [pscustomobject]@{path=$relative; ok=$false; record=$null; error=$_.Exception.Message}
    }
}
