function Classify($line) {
    $unknown = '需确认（保留原文，未视为决定）'
    # Titles are removed, never used as approval evidence. Quotes are opaque
    # objects: neither their uncertainty nor their approval words are evidence.
    $body = ($line -replace '^(决定|决议|待办)\s*[:：]\s*', '').Trim()
