    $discussion = '((仅|只|暂)[^，,。；;]{0,6}(讨论|参考|交流|研究|备选|提案)|供[^，,。；;]{0,6}(讨论|参考)|讨论稿|草案|征求意见|不代表[^，,。；;]*(批准|通过|决定)|不构成[^，,。；;]*(批准|通过|决定)|没有[^，,。；;]*统一|尚无|未获|未经|不确定|不明确)'
    $clauses = @($evidence -split '[，,。；;！!]|但(?:是)?|不过|然而' | Where-Object { $_.Trim() })
    if (!$clauses.Count) { return $unknown }
    $settled = 0
    $historyAwaitingResolution = $false
    $isTodo = $line -match '^待办\s*[:：]'
    foreach ($clause in $clauses) {
        $c = $clause.Trim()
        # Only an explicit completed resolution neutralizes an embedded question.
        # It is scoped to this clause, never to another pending issue in the line.
        if ($c -match '^(?:关于|有关)[^，,。；;？?]+(?:问题|事项)(?:现|目前)?(?:已|已经)(?:解决|明确|确定|达成一致)$') {
            $settled++; $historyAwaitingResolution = $false; continue
        }
        # Historical attributive status is not the status of the new action.
        $c = $c -replace '(?:原先|原本|此前|之前|曾经)(?:待定|未定|未确认|未确定|尚未确定)的', ''
