            # A historical clause alone is unresolved. A later explicit outcome
            # must follow it; present uncertainty (still / to date) cannot be erased.
            if ($c -match '^(此前|之前|原先|原本|过去)' -and $c -notmatch '(仍|至今|目前|现在|如果|若|假如|除非|[？?])') {
                $historyAwaitingResolution = $true; continue
            }
            return $unknown
        }
        if ($isTodo) { continue }
        if ($c -match '^(?:经|经过)(?:确认|批准|表决通过)$') { continue }
        $c = $c -replace '^(?:现已|现在已|目前已)', '已'
        $c = $c -replace '^现(?=决定|确认|确定|批准|否决)', ''
        $resolved = '^(?:(?:会议|会上|委员会|团队|全体|负责人|大家)\s*)?(?:(?:已|已经|正式|最终|明确|一致)\s*)?(?:决定|决议|确定|确认|批准|同意|通过|否决|驳回|拒绝|不批准|不通过|不同意|禁止|严禁|不得|不允许)\s*[^，,。；;]+$'
