        $action = '^(?:(?:首版|本版|本期|本次|新版|第一版|一期|二期)\s*)?(?:(?:按|按照)(?:原计划|原定计划|既定计划)\s*)?(?:(?:已|已经|正式|最终|明确)\s*)?(?:(?:不再|不|只|仅|继续)\s*)?' + '(?:' + $verbs + '[^，,。；;]+|发布|上线|下线|延期)$'
        $prohibition = '^不(?:向|对)[^，,。；;]*' + $verbs + '[^，,。；;]*$'
        $changed = '^[^，,。；;]+(?:改为|改成|调整为|定为)[^，,。；;]+$'
        # A proposal containing a supported action is still a proposal. Completed
        # approval/rejection predicates may take a proposal as their object.
        if ($c -notmatch $resolved -and ($c -match '^(建议|提议|拟|计划|打算)' -or $c -match '(建议|提议|拟|打算)(将|把|改为|改成|调整为|采用|保留|删除|发布|上线|延长)')) { return $unknown }
        if ($c -notmatch $resolved -and $c -notmatch $action -and $c -notmatch $prohibition -and $c -notmatch $changed) { return $unknown }
        if ($c -match '(不|没有|未)(决定|确认|确定)|(?:决定|确认|确定|同意)\s*(讨论|研究|评估|建议|提议)|(?:批准|通过|同意|决定|确认|确定)\s*(情况|状态|结果|与否)|^通过(?:讨论|研究|评估)|(?:禁止|严禁|不得|不允许)\s*$') { return $unknown }
        $settled++
        $historyAwaitingResolution = $false
    }
    if ($historyAwaitingResolution) { return $unknown }
    if ($isTodo) { return '待办（按原文保留）' }
    if (!$settled) { return $unknown }
