[void]$html.Append(@'
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>会议笔记</title>
<style>body{font:16px/1.7 system-ui,sans-serif;max-width:1000px;margin:35px auto;padding:0 20px;color:#233044;background:#f5f7fa}article{background:white;padding:22px;margin:20px 0;border-radius:12px;border:1px solid #dce2ea}input{padding:12px;width:85%;font:inherit}a{color:#135baa}pre{white-space:pre-wrap;word-break:break-word}small{color:#576779}.error{color:#a22222}li{margin:10px 0}:target{background:#fff2a6}summary{cursor:pointer}</style>
<h1>会议笔记</h1><p>本地规则摘录；没有调用 AI 或外部服务。保留原句，不推断负责人、日期或批准状态。各会议按来源独立呈现，冲突不会自动合并。分类依据正文措辞，仅作阅读辅助；“决定／决议”标题不作为批准依据。明确禁止、否决和已确定安排可标为决定；当前仍在讨论、未定、待表决或附有未满足条件的表述，以及无法可靠判定的表述，保留原文并标“需确认”。规则仅覆盖有限句式，不能保证任意语句的语义判断。</p>
<input id="search" aria-label="搜索笔记和原文" placeholder="搜索笔记和原文…"><p id="count"></p>
'@)
[void]$html.Append("<p>本次：新增 $created，跳过 $skipped，失败 $failed。更新时间：$(Esc ((Get-Date).ToString('yyyy-MM-dd HH:mm:ss')))</p>")
foreach ($result in $results) {
    [void]$html.Append("<article><h2>$(Esc $result.path)</h2>")
    if (!$result.ok) {
        [void]$html.Append("<p class='error'>未处理：$(Esc $result.error)</p><p>修复文件后再次运行即可；其他文件已独立处理。历史成果仍保存在 archive 文件夹。</p></article>")
        continue
    }
    $r = $result.record; $id = $r.id
    [void]$html.Append("<p><a href='archive/$id.txt'>下载原始文件（原始字节）</a></p><small>SHA-256：$(Esc $r.sha256)<br>整理时间：$(Esc $r.processed)</small><ul>")
    foreach ($item in $r.items) {
        [void]$html.Append("<li><strong>$(Esc $item.category)</strong>：$(Esc $item.text) <a class='source' href='#s-$id-$($item.line)'>原文第 $($item.line) 行</a></li>")
    }
    [void]$html.Append("</ul><details><summary>查看带行号原文</summary><pre>")
    for ($i=0; $i -lt $r.lines.Count; $i++) { [void]$html.Append("<span id='s-$id-$($i+1)'>$($i+1) | $(Esc $r.lines[$i])</span>`n") }
    [void]$html.Append('</pre></details></article>')
}
[void]$html.Append(@'
<script>const cards=[...document.querySelectorAll('article')];function filter(){let q=document.querySelector('#search').value.toLocaleLowerCase();let n=0;cards.forEach(c=>{c.hidden=!c.textContent.toLocaleLowerCase().includes(q);if(!c.hidden)n++});document.querySelector('#count').textContent=`显示 ${n} / ${cards.length} 个文件`}document.querySelector('#search').addEventListener('input',filter);document.querySelectorAll('.source').forEach(a=>a.addEventListener('click',()=>a.closest('article').querySelector('details').open=true));filter();</script></html>
'@)
WriteAtomic (Join-Path $out 'index.html') $html.ToString()
WriteAtomic (Join-Path $out 'status.json') (ConvertTo-Json -InputObject @($results | ForEach-Object { [pscustomobject]@{path=$_.path; success=$_.ok; error=$_.error} }) -Depth 4)
Write-Host "Created: $created; skipped: $skipped; failed: $failed"
Write-Host "Notes: $(Join-Path $out 'index.html')"
} finally { if ($lock) { $lock.Dispose() } }
